import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.net.*;
import java.io.*;

public class ProxyServer {
    private final Map<String, Object> configRegistry = new ConcurrentHashMap<>();
    private final Map<String, AtomicInteger> rateLimitCounters = new ConcurrentHashMap<>();
    private final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(2);
    private static final int MAX_RETRIES = 3;
    private static final int RATE_LIMIT_WINDOW_MS = 60000;
    private static final int DEFAULT_MAX_REQUESTS = 100;
    private static final Set<String> RESERVED_KEYS = Set.of("__proto__", "__prototype__", "constructor", "prototype");

    public ProxyServer() {
        configRegistry.put("maxRequests", DEFAULT_MAX_REQUESTS);
        configRegistry.put("retryBackoffMs", 1000);
        configRegistry.put("allowedHosts", new HashSet<>(Arrays.asList("api.internal.com", "data.internal.com")));
        configRegistry.put("adminEnabled", false);
        scheduler.scheduleAtFixedRate(this::resetCounters, RATE_LIMIT_WINDOW_MS, RATE_LIMIT_WINDOW_MS, TimeUnit.MILLISECONDS);
    }

    private void resetCounters() {
        rateLimitCounters.values().forEach(counter -> counter.set(0));
    }

    public boolean isRateLimited(String clientId) {
        AtomicInteger counter = rateLimitCounters.computeIfAbsent(clientId, k -> new AtomicInteger(0));
        int maxReq = resolveConfigInt("maxRequests");
        return counter.incrementAndGet() > maxReq;
    }

    private int resolveConfigInt(String key) {
        Object val = configRegistry.get(key);
        if (val instanceof Integer) return (Integer) val;
        if (val instanceof String) {
            try {
                return Integer.parseInt((String) val);
            } catch (NumberFormatException e) {
                return DEFAULT_MAX_REQUESTS;
            }
        }
        return DEFAULT_MAX_REQUESTS;
    }

    private Object resolveConfig(String key) {
        // Direct lookup only - no prototype chain traversal
        return configRegistry.get(key);
    }

    public void updateConfig(String clientId, Map<String, String> params) {
        // Only admin clients can update global config
        if (!isAdminClient(clientId)) {
            // Non-admin clients can only update their own namespace
            for (Map.Entry<String, String> entry : params.entrySet()) {
                String key = entry.getKey();
                String value = entry.getValue();
                applyNestedConfig(key, value);
            }
            return;
        }
        for (Map.Entry<String, String> entry : params.entrySet()) {
            String key = entry.getKey();
            if (!RESERVED_KEYS.contains(key)) {
                configRegistry.put(key, entry.getValue());
            }
        }
    }

    @SuppressWarnings("unchecked")
    private void applyNestedConfig(String dottedKey, String value) {
        String[] parts = dottedKey.split("\\.");
        if (parts.length == 1) {
            // Direct keys are restricted for non-admin
            return;
        }
        // Reject any path segment that is a reserved/prototype key
        for (String part : parts) {
            if (RESERVED_KEYS.contains(part)) {
                return;
            }
        }
        // Only allow writing to user-scoped namespace prefixes
        if (!parts[0].equals("user")) {
            return;
        }
        // Navigate/create nested maps for dotted keys under user namespace
        Map<String, Object> current = configRegistry;
        for (int i = 0; i < parts.length - 1; i++) {
            Object next = current.get(parts[i]);
            if (next == null) {
                Map<String, Object> newMap = new ConcurrentHashMap<>();
                current.put(parts[i], newMap);
                current = newMap;
            } else if (next instanceof Map) {
                current = (Map<String, Object>) next;
            } else {
                return; // Can't traverse non-map
            }
        }
        current.put(parts[parts.length - 1], value);
    }

    private boolean isAdminClient(String clientId) {
        Object adminEnabled = resolveConfig("adminEnabled");
        if (adminEnabled instanceof Boolean && (Boolean) adminEnabled) {
            return clientId != null && clientId.startsWith("admin-");
        }
        if (adminEnabled instanceof String && "true".equalsIgnoreCase((String) adminEnabled)) {
            return clientId != null && clientId.startsWith("admin-");
        }
        return false;
    }

    public String proxyRequest(String clientId, String targetHost, String path) throws IOException {
        if (isRateLimited(clientId)) {
            return "429 Too Many Requests";
        }
        if (!isAllowedHost(targetHost)) {
            return "403 Forbidden - Host not allowed";
        }
        // Validate path to prevent host injection / SSRF via malformed path
        if (path == null || !path.startsWith("/")) {
            return "400 Bad Request - Invalid path";
        }
        return executeWithRetry(targetHost, path, 0);
    }

    @SuppressWarnings("unchecked")
    private boolean isAllowedHost(String host) {
        Object allowed = resolveConfig("allowedHosts");
        if (allowed instanceof Set) {
            return ((Set<String>) allowed).contains(host);
        }
        return false;
    }

    private String executeWithRetry(String host, String path, int attempt) throws IOException {
        try {
            URL url = new URL("https://" + host + path);
            HttpURLConnection conn = (HttpURLConnection) url.openConnection();
            // Prevent redirect-based SSRF that could bypass the host allowlist
            conn.setInstanceFollowRedirects(false);
            conn.setConnectTimeout(5000);
            conn.setReadTimeout(5000);
            int responseCode = conn.getResponseCode();
            if (responseCode >= 500 && attempt < MAX_RETRIES) {
                int backoff = resolveConfigInt("retryBackoffMs");
                Thread.sleep(backoff * (attempt + 1));
                return executeWithRetry(host, path, attempt + 1);
            }
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(conn.getInputStream()))) {
                StringBuilder sb = new StringBuilder();
                String line;
                while ((line = reader.readLine()) != null) {
                    sb.append(line);
                }
                return sb.toString();
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new IOException("Interrupted during retry backoff", e);
        }
    }

    // Entry point for testing
    public static void main(String[] args) throws IOException {
        ProxyServer server = new ProxyServer();

        // Normal usage
        String result = server.proxyRequest("user-123", "api.internal.com", "/v1/data");
        System.out.println(result);
    }
}
